if history.exists():
    logs = pd.DataFrame(json.loads(line) for line in history.read_text(encoding='utf-8').splitlines())
    for col in ['loss','eval_loss']:
        if col in logs: plt.plot(logs['step'],logs[col],marker='.',label=col)
